Original prompt:
' + $('VP Prep').first().json.prompt } ] } }}

parameters.jsCode:
// 'Sort & Cap Scenes' runs at most CAP (8) scenes per pass, so a project
// with more approved scenes than that needs several passes. The batch used
// to walk straight from the last approved clip to the final-settings gate,
// which left the tail ungenerated AND kept the execution alive — hiding the
// site's own "Start the next batch" button, whose whole condition is that
// nothing is running. The producer's only way through was Pause + Resume.
//
// So the batch asks for itself: any approved scene still without a clip —
// or owed a video regeneration — means another pass is owed. Same rule as
// `pending` in Sort & Cap Scenes; keep the two together.
const recs = $input.all();
const remaining = recs.filter((r) => {
  const f = r.json.fields || {};
  return !String(f['Scene Final URL'] || '').startsWith('http') || f['Regenerează Video'] === true;
}).length;
// 12 passes = 96 scenes, far past anything real. A scene that can never
// finish (permanent content refusal) must not spin the loop forever — it
// falls through to the gate and the producer sees it unfinished.
const MAX_PASSES = 12;
const more = remaining > 0 && $runIndex + 1 < MAX_PASSES;
if (remaining > 0 && !more) console.log('Batch loop: giving up after ' + ($runIndex + 1) + ' passes with ' + remaining + ' scene(s) still unfinished.');
else console.log('Batch pass ' + ($runIndex + 1) + ' done; ' + remaining + ' scene(s) still to generate.');
return [{ json: { remaining, more, pass: $runIndex + 1 } }];

// The image loop must NOT consume Loop Audio's done output directly: items
// that skipped synthesis re-enter that loop carrying the PROJECT record
// (Needs Voice? -> AB Current Scene -> AB Load Project -> AB No Speech?),
// and one of those reaching Build Image Request kills the whole batch with
// 'Scene ... has no image prompt.' Every stage re-enters from a clean list
// for exactly this reason.
//
// Sort & Cap's own items are replayed verbatim: same records, same
// pending-first order (the n-1 image chain and the regen's recs[i-1] both
// assume that order), and the audio stage between them writes only voice
// fields, so the image-field snapshot is exactly as fresh as it was when
// the image loop read Sort & Cap directly.
return $('Sort & Cap Scenes').all().map(r => ({ json: r.json }));

// Submit Video failed after its own three quick retries. That is usually
// the Flow account being throttled — 'captcha_quality:
// PUBLIC_ERROR_UNUSUAL_ACTIVITY after 5 attempts' killed the whole Vegas
// batch at 8981 — and the cure is time, not a fourth attempt one second
// later. Hold a minute and try again, at most MAX times per scene per run;
// then die with the last reason, exactly as before. The Wait is 60s ON
// PURPOSE: under 65s n8n keeps the execution in memory, so this counter
// (static data) survives; a longer Wait suspends the run to the database
// and the count would not.
// (Sort & Cap Scenes resets the counters at the start of every pass.)
const sd = $getWorkflowStaticData('global');
sd.submitCooldowns = sd.submitCooldowns || {};
const key = $('Current Scene').first().json.id;
const n = (sd.submitCooldowns[key] || 0) + 1;
sd.submitCooldowns[key] = n;
const MAX = 20;
const j = $input.first().json || {};
const last = String((j.error && (j.error.message || j.error.description)) || j.message || JSON.stringify(j)).slice(0, 300);
if (n > MAX) throw new Error('Submit Video kept failing after ' + MAX + ' cooldowns of 60s — last reason: ' + last);
console.log('Submit Video failed (' + n + '/' + MAX + '), cooling down 60s: ' + last);
return [{ json: { cooldown: n, lastError: last } }];

// Same cooldown as 'Submit Cooldown Guard', for the regeneration submit
// inside the video gate. Re-feeds the regen payload, exactly as 'Regen
// Resubmit Guard' does, because Submit Video Regen reads $json.
const sd = $getWorkflowStaticData('global');
sd.submitCooldowns = sd.submitCooldowns || {};
const payload = $('Prep Video Regen').first().json;
const key = 'regen:' + payload.id;
const n = (sd.submitCooldowns[key] || 0) + 1;
sd.submitCooldowns[key] = n;
const MAX = 20;
const j = $input.first().json || {};
const last = String((j.error && (j.error.message || j.error.description)) || j.message || JSON.stringify(j)).slice(0, 300);
if (n > MAX) throw new Error('Submit Video Regen kept failing after ' + MAX + ' cooldowns of 60s — last reason: ' + last);
console.log('Submit Video Regen failed (' + n + '/' + MAX + '), cooling down 60s: ' + last);
return [{ json: payload }];

const item = $input.first().json;
const status = (item.status || '').toLowerCase();
// Polls are counted PER SCENE in static data, not with $runIndex — which
// counts every poll of the execution across all scenes, and a pass now
// covers the whole film (Sort & Cap Scenes resets sd.polls each pass).
// 30s a poll ('Wait Video'); 120 = one hour a clip, sized for the
// low-priority Veo queue. A clip that overruns it is treated as a FAILED
// job — 'Resubmit Guard' resubmits it — rather than killing the film.
const sd = $getWorkflowStaticData('global');
sd.polls = sd.polls || {};
const sceneId = $('Current Scene').first().json.id;
sd.polls[sceneId] = (sd.polls[sceneId] || 0) + 1;
const MAX_POLLS = 120;
const raw = JSON.stringify(item);
const done = status === 'completed' || raw.includes('flow-content.google/video');
let failed = status === 'failed' || status === 'error' || status === 'cancelled';
if (!done && !failed && sd.polls[sceneId] > MAX_POLLS) {
  console.log('Scene ' + sceneId + ': video job still not done after ' + MAX_POLLS + ' polls — treating as failed so it gets resubmitted.');
  failed = true;
  item.error = 'polling timed out after ' + MAX_POLLS + ' polls';
}
// Failed jobs are routed to a resubmit branch instead of throwing here —
// Google intermittently fails generations with VIDEO_GENERATION_TIMED_OUT
// and a resubmit usually succeeds.
return [{ json: Object.assign({}, item, { done: done && !failed, jobFailed: failed }) }];

const item = $input.first().json;
function find(obj, pred) {
  let f = null;
  (function w(o) { if (f) return;
    if (typeof o === 'string') { if (pred(o)) f = o; return; }
    if (Array.isArray(o)) { for (const v of o) { if (f) return; w(v); } return; }
    if (o && typeof o === 'object') { for (const k of Object.keys(o)) { if (f) return; w(o[k]); } }
  })(obj);
  return f;
}
let url = null, mediaId = null;
try { const gv = item.response && item.response.media && item.response.media[0] && item.response.media[0].video && item.response.media[0].video.generatedVideo; if (gv) { if (typeof gv.fifeUrl === 'string') url = gv.fifeUrl; if (typeof gv.mediaGenerationId === 'string') mediaId = gv.mediaGenerationId; } } catch (e) {}
if (!url) url = find(item, s => s.startsWith('http') && s.includes('flow-content.google') && s.includes('/video'));
if (!mediaId) mediaId = find(item, s => s.includes('-video:'));
if (!url && !mediaId) throw new Error('No video url or mediaId in completed job. Head: ' + JSON.stringify(item).slice(0, 800));
return [{ json: { Video_Signed_URL: url || '', Video_Media_Id: mediaId || '' } }];

const sd = $getWorkflowStaticData('global');
sd.prevImageUrl = '';
sd.prevImageId = '';
sd.anchorId = '';
// Every per-scene counter in this workflow lives here and is reset per
// pass: video polls / resubmits (batch loop), regen polls / resubmits (the
// gate), multi-voice polls, motion-prompt rewrites, submit cooldowns.
// They are keyed by scene id because $runIndex counts a node's runs across
// the WHOLE execution — and a pass now covers the whole film.
sd.polls = {};
sd.resubmits = {};
sd.regenPolls = {};
sd.regenResubmits = {};
sd.multiPolls = {};
sd.rewrites = {};
sd.submitCooldowns = {};
sd.imgRewrites = {};
sd.muxPolls = {};
const items = $input.all().slice();
const ord = it => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
// "Done" is judged on the CLIP and the regen flags, never on the status
// text. It used to be the text ('Așteaptă Aprobare Video' / 'Finalizat'),
// and `VP Apply` stamped exactly that text on a scene whose clip had just
// been REFUSED by the video filter — so a refused scene sorted as finished,
// fell behind the cap on any film longer than 8 scenes, and was never
// generated again (Vegas, 71 scenes: 117, 118, 203 and 204 sat like that).
const pending = it => {
  const f = it.json.fields || {};
  const hasClip = String(f['Scene Final URL'] || '').startsWith('http');
  const flagged = f['Regenerează Video'] === true || f['Regenerează Imagine'] === true || f['Regenerează Voce'] === true;
  return !hasClip || flagged;
};
items.sort((a, b) => {
  const pa = pending(a), pb = pending(b);
  if (pa !== pb) return pa ? -1 : 1;
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
  return a.json.id < b.json.id ? -1 : 1;
});
if (!items.length) throw new Error('No approved scenes found for this project.');
// A pass covers the WHOLE film: every take, every image, one combined gate,
// every clip, one video gate. The cap was 8 until 2026-09-01, which turned a
// 71-scene film into nine rounds of approvals; the site mirrors this number
// in MEDIA_BATCH_CAP. 200 is a sanity bound (a 12-minute film is ~90
// scenes), not a chunk size. Pending-first sorting stays so a repeat pass
// (refused scenes, regen flags) still converges.
const CAP = 200;
if (items.length > CAP) {
  console.log('Sort & Cap: ' + items.length + ' approved scenes, running ' + CAP + '; ' + (items.length - CAP) + ' left for the next run.');
}
return items.slice(0, CAP);

const f = $json.fields || {};
const prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
if (!prompt) throw new Error('Scene ' + $json.id + ' has no image prompt.');
const aspect = $('Receive Batch Input').first().json.Aspect_Ratio === '9:16' ? '9:16' : '16:9';

// The producer's own reference photo (uploaded on the creation form, stored
// as Editing Options.refImage) is GROUND TRUTH for the FILM'S FIRST SCENE
// (Ordine 1, the hook). It wins over the n-1 chaining below and skips the
// similarity guard — reproducing this reference faithfully is the point.
let userRef = '';
try { userRef = String((JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}).refImage || ''); } catch (e) {}
const isFirstScene = Number(f['Ordine Scenă']) === 1;

// Previous scene's generated image = reference for this one (n-1 -> n).
// Read it from the PREVIOUS RUN of Decode Scene Image: run data survives Wait
// suspensions, unlike $getWorkflowStaticData which resets on every resume in
// test executions (proven in execution 661 where references never got sent).
let prevUrl = '';
let prevPrompt = '';
try {
  if ($runIndex > 0) {
    const prev = $('Decode Scene Image').all(0, $runIndex - 1);
    if (prev && prev[0] && prev[0].json && prev[0].json.url) prevUrl = prev[0].json.url;
    const prevReq = $('Build Image Request').all(0, $runIndex - 1);
    if (prevReq && prevReq[0] && prevReq[0].json) prevPrompt = prevReq[0].json.rawPrompt || '';
  }
} catch (e) { prevUrl = ''; }

// Reference guard: chaining exists for CHARACTER/wardrobe consistency. On
// homogeneous subjects (same car on the same road every scene) the edit
// model just reproduces the reference and the whole film collapses into
